<?php namespace App\Models; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; class Activity extends Model{use HasFactory; protected $fillable=['company_id','opportunity_id','type','scheduled_at','description','result','status']; protected function casts():array{return ['scheduled_at'=>'datetime'];} public function company(){return $this->belongsTo(Company::class);} public function opportunity(){return $this->belongsTo(Opportunity::class);}}
